<form class="form-grid" method="post" action="<?= e($projectFormAction) ?>"><?= csrf_field() ?><label>Project name<input name="name" value="<?= e($projectEditing['name']??'') ?>" maxlength="160" required></label><label>Identifier<input name="identifier" value="<?= e($projectEditing['identifier']??'') ?>" maxlength="8" pattern="[a-zA-Z][a-zA-Z0-9]{1,7}" placeholder="LIFE" required></label><label>Project type<select name="kind"><?php foreach(['personal'=>'Personal','study'=>'Study','business'=>'Business','client'=>'Client'] as $value=>$label): ?><option value="<?= $value ?>" <?= ($projectEditing['kind']??'personal')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Project lead<select name="lead_id"><option value="">Not assigned</option><?php foreach($people as $person):if(!$person['active']&&($projectEditing['lead_id']??null)!=$person['id'])continue; ?><option value="<?= e($person['id']) ?>" <?= ($projectEditing['lead_id']??'')==$person['id']?'selected':'' ?>><?= e($person['name']) ?></option><?php endforeach; ?></select></label><label>Start date<input type="date" name="start_date" value="<?= e($projectEditing['start_date']??'') ?>"></label><label>Target date<input type="date" name="target_date" value="<?= e($projectEditing['target_date']??'') ?>"></label><label class="full">Linked website / business (optional)<select name="website_id"><option value="">No website link</option><?php foreach($websites as $website): ?><option value="<?= e($website['id']) ?>" <?= ($projectEditing['website_id']??'')==$website['id']?'selected':'' ?>><?= e(($website['business_name']?$website['business_name'].' · ':'').$website['name']) ?></option><?php endforeach; ?></select></label><label class="full">Description<textarea name="description" rows="3" maxlength="10000"><?= e($projectEditing['description']??'') ?></textarea></label><div class="full"><button><?= $projectEditing?'Save project':'Create project' ?></button></div></form>
